REVOKE ALL ON FUNCTION public.handle_signup() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_set_role(uuid,public.app_role) FROM anon;
REVOKE ALL ON FUNCTION public.owns_supplier(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.owns_supplier(uuid) TO anon,authenticated;
REVOKE ALL ON FUNCTION public.public_product(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_product(uuid) TO anon,authenticated;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon,authenticated;
CREATE FUNCTION public.admin_verify_supplier(supplier uuid, decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF decision NOT IN ('approved','rejected','pending') THEN RAISE EXCEPTION 'Invalid decision'; END IF; UPDATE public.supplier_profiles SET verification_status=decision WHERE id=supplier; IF NOT FOUND THEN RAISE EXCEPTION 'Supplier not found'; END IF; INSERT INTO public.supplier_verification_history(supplier_id,admin_id,decision) VALUES(supplier,auth.uid(),decision); END $$;
REVOKE ALL ON FUNCTION public.admin_verify_supplier(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_verify_supplier(uuid,text) TO authenticated;
CREATE FUNCTION public.validate_cart_quantity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE minimum integer; BEGIN SELECT moq INTO minimum FROM public.products WHERE id=NEW.product_id; IF minimum IS NULL OR NEW.quantity<minimum THEN RAISE EXCEPTION 'Quantity below minimum order'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cart_quantity_validation BEFORE INSERT OR UPDATE ON public.cart_items FOR EACH ROW EXECUTE FUNCTION public.validate_cart_quantity();
CREATE FUNCTION public.guard_campaign() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='open' AND NOT public.public_product(NEW.product_id) THEN RAISE EXCEPTION 'Campaign requires an approved published product'; END IF; IF TG_OP='UPDATE' AND (NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR NEW.product_id IS DISTINCT FROM OLD.product_id) THEN RAISE EXCEPTION 'Campaign ownership cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER campaign_validation BEFORE INSERT OR UPDATE ON public.group_buying_campaigns FOR EACH ROW EXECUTE FUNCTION public.guard_campaign();